func (s *Service) forecastEvidence(ctx context.Context, window string, f ProfileFilter) ([]ForecastEvidence, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT payload FROM analytics_forecasts WHERE window_id=? AND rowid<=? AND issued_ms<=? ORDER BY issued_ms,id`, window, f.ForecastsThrough, f.At)
	if err != nil {
		return nil, err
	}
	out := []ForecastEvidence{}
	for rows.Next() {
		var raw string
		var forecast QuotaForecast
		if err = rows.Scan(&raw); err == nil {
			err = json.Unmarshal([]byte(raw), &forecast)
		}
		if err != nil {
			rows.Close()
			return nil, err
		}
		if forecast.Through > f.Through || forecast.ObservationsThrough > f.ObservationsThrough {
			continue
		}
		out = append(out, ForecastEvidence{Forecast: forecast, Results: []ForecastResult{}})
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	for i := range out {
		rows, err = s.db.QueryContext(ctx, `SELECT payload FROM analytics_forecast_results WHERE forecast_id=? AND rowid<=? AND settled_ms<=? ORDER BY rowid`, out[i].Forecast.ID, f.VerificationsThrough, f.At)
		if err != nil {
			return nil, err
		}
		for rows.Next() {
			var raw string
			var result ForecastResult
			if err = rows.Scan(&raw); err == nil {
				err = json.Unmarshal([]byte(raw), &result)
			}
			if err != nil {
				rows.Close()
				return nil, err
			}
			if result.Through > f.Through || result.ObservationsThrough > f.ObservationsThrough {
				continue
			}
			out[i].Results = append(out[i].Results, result)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return nil, err
		}
	}
	return out, nil
}

func lastVerification(c WindowComparison, ledger []ForecastEvidence) *ForecastResult {
	var best *ForecastResult
	for _, evidence := range ledger {
		if len(evidence.Results) == 0 {
			continue
		}
		r := evidence.Results[len(evidence.Results)-1]
		if r.State != "verified" || r.EstimatorID != c.EstimatorID || r.RuleID != c.RuleID || r.OriginTime < c.SegmentStart {
			continue
		}
		if best == nil || r.Observed > best.Observed || r.Observed == best.Observed && (r.Issued > best.Issued || r.Issued == best.Issued && r.Target < best.Target) {
			copy := r
			best = &copy
		}
	}
	return best
}
